package es.nivel36.janus.policy.appuser;
import org.springframework.security.core.Authentication; import org.springframework.stereotype.Component; import es.nivel36.janus.security.ActorResolver;
@Component("appUserAuthorization") public class AppUserAuthorizationAdapter { private final ActorResolver actors; private final ViewAppUserPolicy view=new ViewAppUserPolicy(); private final CreateAppUserPolicy create=new CreateAppUserPolicy(); private final UpdateAppUserPolicy update=new UpdateAppUserPolicy(); private final UpdateCurrentAppUserPolicy updateCurrent=new UpdateCurrentAppUserPolicy(); private final DeleteAppUserPolicy delete=new DeleteAppUserPolicy(); public AppUserAuthorizationAdapter(ActorResolver actors){this.actors=actors;} public boolean canView(Authentication a){return view.allows(actors.resolve(a),null);} public boolean canCreate(Authentication a){return create.allows(actors.resolve(a),null);} public boolean canUpdate(Authentication a){return update.allows(actors.resolve(a),null);} public boolean canUpdateCurrent(Authentication a){return updateCurrent.allows(actors.resolve(a),null);} public boolean canDelete(Authentication a){return delete.allows(actors.resolve(a),null);} }
